  // Erzeugt automatisch eine "in welchem Jahr war …?"-Frage aus jedem Geschichte-Eintrag — so
  // bleibt "Es war einmal in Deutschland" nicht nur zum Lesen, sondern taucht auch interaktiv
  // im Deutschland-Quiz auf.
  function historyQuizBank() {
    return Object.entries(GERMAN_HISTORY_TODAY).filter(([key]) => HISTORY_TITLES[key]).map(([key, entry]) => {
      const title = HISTORY_TITLES[key];
      const correctYear = entry.year;
      const wrongYears = new Set();
      let attempts = 0;
      while (wrongYears.size < 3 && attempts < 50) {
        attempts++;
        const offset = (Math.floor(Math.random() * 20) + 3) * (Math.random() < 0.5 ? -1 : 1);
        const y = correctYear + offset;
        if (y !== correctYear && y > 0 && y < 2026) wrongYears.add(y);
      }
      const options = Core.shuffle([String(correctYear), ...[...wrongYears].map(String)]);
      return [`In welchem Jahr war ${title}?`, options, [options.indexOf(String(correctYear))], "Geschichte & Politik"];
    });
  }
  function bankQuiz(topic) {
    const allQuestions = [...DEUTSCHLAND_QUIZ, ...historyQuizBank()];
    const pool = topic ? allQuestions.filter(([, , , t]) => t === topic) : allQuestions;
    return Core.shuffle(pool).map(([prompt, options, correctIdx]) => {
      // Optionen mischen, aber korrekte Indizes mitverschieben
      const withIdx = options.map((o, i) => ({ o, correct: correctIdx.includes(i) }));
      const shuffled = Core.shuffle(withIdx);
      return {
        prompt,
        options: shuffled.map((x) => x.o),
        correct: shuffled.reduce((acc, x, i) => (x.correct ? [...acc, i] : acc), []),
        explain:
          correctIdx.length > 1
            ? `Richtig sind: ${correctIdx.map((i) => options[i]).join(" und ")}.`
            : `Richtig ist: ${options[correctIdx[0]]}.`,
        multi: correctIdx.length > 1,
      };
    });
  }

  function getQuizTopics() {
    return [...new Set(DEUTSCHLAND_QUIZ.map((q) => q[3]))];
  }

  /* ---------------------------------------------------------
     HOMOPHONE — gleich klingen, anders schreiben
     ---------------------------------------------------------
     Früher eine eigene, abweichend gestaltete Extra-Ansicht. Jetzt eine
     ganz normale Übungskategorie: dadurch bekommt sie automatisch dasselbe
     Kartendesign, dieselbe Farbcodierung bei richtig/falsch, den
     Ergebnis-Bildschirm mit Auswertung, Punkte, Abzeichen und die
     Anrechnung auf die Sammelfüchse — genau wie „Artikel (der/die/das)“.
     --------------------------------------------------------- */
  const HOMOPHONE_PAARE = [
    ["mehr", "eine größere Menge, zusätzlich", "Meer", "das große, salzige Gewässer", "A2"],
    ["Wal", "das riesige Meerestier", "Wahl", "die Entscheidung zwischen mehreren Möglichkeiten", "A2"],
    ["Rat", "ein Vorschlag oder eine Empfehlung", "Rad", "der runde Teil an einem Fahrzeug", "A2"],
    ["Lied", "ein gesungenes Musikstück", "Lid", "die Haut, die man über das Auge schließt", "A2"],
    ["Tod", "das Ende des Lebens", "tot", "nicht mehr lebendig", "A2"],
    ["seid", "ihr seid — die Form von „sein“", "seit", "ab einem bestimmten Zeitpunkt", "A2"],
    ["Saite", "der gespannte Draht an einer Gitarre", "Seite", "ein Blatt in einem Buch", "B1"],
    ["malen", "ein Bild mit Farbe machen", "mahlen", "Korn zu Mehl zerkleinern", "B1"],
    ["Lehre", "eine Ausbildung oder eine wichtige Erkenntnis", "Leere", "der Zustand, wenn nichts darin ist", "B1"],
    ["Stiel", "der Griff eines Werkzeugs oder der Stängel einer Pflanze", "Stil", "die persönliche Art, wie etwas gemacht wird", "B1"],
    ["Mine", "die Farbfüllung in einem Stift", "Miene", "der Gesichtsausdruck einer Person", "B1"],
    ["Waise", "ein Kind ohne Eltern", "Weise", "die Art und Weise, wie etwas geschieht", "B1"],
    ["Wende", "ein grundlegender Richtungswechsel", "Wände", "mehrere Mauern eines Raums", "B1"],
    ["Leib", "der Körper eines Menschen (gehoben)", "Laib", "ein ganzes rundes Brot", "B2"],
    ["Ähre", "der obere Teil einer Getreidepflanze mit den Körnern", "Ehre", "hohes Ansehen und Respekt", "B2"],
    ["Grad", "die Einheit für Temperatur oder Winkel", "Grat", "die scharfe Kante eines Berges", "B2"],
    ["Lerche", "ein kleiner Singvogel", "Lärche", "ein Nadelbaum, der im Herbst die Nadeln verliert", "B2"],
    ["Moor", "ein nasses, weiches Sumpfgebiet", "Mohr", "veraltete, heute vermiedene Bezeichnung für einen dunkelhäutigen Menschen", "C1"],
    ["wieder", "noch einmal, erneut", "wider", "gegen etwas — wie in „wider Erwarten“", "C1"],
    ["Verse", "mehrere Zeilen eines Gedichts", "Ferse", "der hintere Teil des Fußes", "B2"],
    ["Weg", "die Strecke von einem Ort zum anderen", "weg", "nicht mehr da, fort", "A2"],
    ["Sohle", "die Unterseite eines Schuhs", "Sole", "salzhaltiges Wasser, etwa in einer Saline", "C1"],
    ["Bord", "das Regalbrett oder die Seite eines Schiffs", "Bort", "veraltet für den Rand einer Fläche", "C1"],
    ["Gäste", "mehrere eingeladene Besucher", "Geste", "eine Bewegung, die etwas ausdrückt", "B1"],
    ["Ross", "ein Pferd (gehoben)", "Rost", "die rotbraune Schicht auf altem Eisen", "B2"],
    ["Meile", "eine alte Längeneinheit", "Maile", "verschicke eine E-Mail (umgangssprachlich)", "B2"],
    ["Wagen", "das Fahrzeug", "wagen", "etwas Riskantes tun, sich trauen", "B1"],
    ["Reise", "eine Fahrt an einen entfernten Ort", "reiße", "ich reiße — von „reißen“", "B1"],
    ["Bad", "der Raum zum Waschen", "bat", "hat gebeten — von „bitten“", "B1"],
    ["Rind", "das Nutztier, von dem Rindfleisch stammt", "rinnt", "fließt langsam — von „rinnen“", "B2"],
    ["Ries", "eine Zählmenge Papier (500 Blatt)", "Reis", "das weiße Getreidekorn als Beilage", "C1"],
    ["Laden", "das Geschäft, in dem man einkauft", "laden", "etwas in ein Fahrzeug packen oder Strom aufnehmen", "A2"],
  ];
  function bankHomophone() {
    // Jedes Paar liefert ZWEI Aufgaben — einmal wird nach dem einen, einmal nach dem
    // anderen Wort gefragt. So wird der Unterschied wirklich in beide Richtungen geübt,
    // statt immer nur eine Seite abzufragen.
    const fragen = [];
    HOMOPHONE_PAARE.forEach(([a, aBed, b, bBed, level]) => {
      fragen.push({
        prompt: `„${aBed}“ — wie schreibt man dieses Wort?`,
        options: [a, b],
        correct: [0],
        explain: `„${a}“ = ${aBed}. Gleich ausgesprochen, aber „${b}“ bedeutet: ${bBed}.`,
        level,
      });
      fragen.push({
        prompt: `„${bBed}“ — wie schreibt man dieses Wort?`,
        options: [a, b],
        correct: [1],
        explain: `„${b}“ = ${bBed}. Gleich ausgesprochen, aber „${a}“ bedeutet: ${aBed}.`,
        level,
      });
    });
    // Antwortreihenfolge mischen, damit die richtige Lösung nicht bei jeder zweiten
    // Frage an derselben Stelle steht.
    return Core.shuffle(fragen).map((q) => {
      if (Math.random() < 0.5) return q;
      return { ...q, options: [q.options[1], q.options[0]], correct: [q.correct[0] === 0 ? 1 : 0] };
    });
  }

